 // Compiled inside the app controller; all calculations live in src/strategy.js or the imported engines.
 const T=globalThis.RodavoltStrategy,L=globalThis.RodavoltLegacy;
 const pct=n=>n===null?'Sem base':number(n)+'%';
 const input=(name,label,value,extra='')=>`<label class="r-field">${label}<input name="${name}" value="${esc(value)}" ${extra}></label>`;
 const choice=(name,label,value,options)=>`<label class="r-field">${label}<select name="${name}">${options.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></label>`;
 function strategyView(){return heading('CENTRO DE ESTRATÉGIA','Do primeiro carro à próxima etapa.','Decida como investir, acompanhe o plano e confira as regras que sustentam o crescimento.')+tabs([['hub','Tudo do centro'],['decision','Central de decisão'],['master','Planejamento mestre'],['allocation','Alocação de capital'],['expansion','Expansão & renovação'],['policies','Políticas da empresa']],strategyTab,'strategy-tab')+({hub:strategyHub,decision:growth,master:masterView,allocation:allocationView,expansion:expansionView,policies:policiesView}[strategyTab])();}

 const strategyDestinations=[
  {key:'decision',title:'Simulador empresarial',tag:'01 · CENTRAL DE DECISÃO',description:'Quanto investir, quando comprar e como sustentar o crescimento.',items:['Premissas de capital, aluguel, custos, loja e financiamento','Projeção da frota, caixa, dívida e patrimônio','Fluxo mensal e anual, aportes, amortização e reserva','Retorno, equilíbrio, comprar agora ou esperar e cenários próprios']},
  {key:'master',title:'Planejamento mestre',tag:'02 · DIREÇÃO E METAS',description:'Defina a direção da empresa e acompanhe cada etapa.',items:['Missão, visão e nove frentes futuras','Roadmap automático e estágios de 1 a 1.000 carros','Capital e resultado necessários para o próximo marco','Marcos por frota, receita, lucro, caixa, ROI, tempo ou conclusão manual']},
  {key:'allocation',title:'Alocação de capital',tag:'03 · RETORNO POR CARRO',description:'Confira onde o dinheiro foi aplicado e de onde vem o retorno.',items:['Valor de compra e resultado registrado por veículo','Ranking de ROI e comparação de retornos','Payback estimado com base no histórico','Abertura dos lançamentos que compõem cada valor']},
  {key:'expansion',title:'Expansão da frota',tag:'04 · CAPACIDADE E CRESCIMENTO',description:'Compare formas de crescer com o capital disponível.',items:['Conservadora, balanceada e agressiva com parâmetros visíveis','Financiamento Price/SAC, reserva e cobertura das parcelas','Crescimento composto com caixa e venda recorrente','Partida por fechamento, candidatos à venda e cenários preservados']},
  {key:'renewal',title:'Renovação de veículos',tag:'04 · VENDA E REINVESTIMENTO',description:'Compare manter o carro com vender em diferentes meses.',items:['Até 12 datas de venda comparadas com manter até o fim','Patrimônio, caixa, capital reciclado e frota por alternativa','Reinvestimento limitado por reserva e cobertura das parcelas','Memória mensal, dívida quitada, custos de venda e bloqueios']},
  {key:'policies',title:'Políticas da empresa',tag:'05 · REGRAS DO PROPRIETÁRIO',description:'Estabeleça limites e confira se o cenário os atende.',items:['Os 14 limites do centro antigo, todos opcionais','ROI, payback, reserva, financiamento e alavancagem','Metas de ocupação, perdas, margem e crescimento','Políticas livres e aplicação de reserva/teto financiável ao rascunho']}
 ];
 function strategyHub(){return `<div class="r-center-intro"><h2>O que veio do Centro de Estratégia</h2><p>Abra uma área abaixo ou use os acessos diretos no menu. Os simuladores e formulários funcionam nesta demonstração local; os registros financeiros e da frota são ilustrativos.</p></div><div class="r-strategy-directory">${strategyDestinations.map(d=>`<section class="r-panel r-directory-item"><span class="r-eyebrow">${d.tag}</span><h2>${d.title}</h2><p class="r-caption">${d.description}</p><ul>${d.items.map(t=>`<li>${t}</li>`).join('')}</ul><button type="button" class="r-button r-primary" data-strategy-destination="${d.key}">Abrir ${d.title.toLocaleLowerCase('pt-BR')} →</button></section>`).join('')}</div><div class="r-note"><strong>Conexão com a gestão:</strong> a comparação projetado × realizado continua em uma tela própria, ligada aos lançamentos de demonstração. ${btn('Abrir projetado × realizado','go-compare')}</div>`;}
 function openStrategyDestination(destination){if(!strategyDestinations.some(d=>d.key===destination))return;strategyTab=destination==='renewal'?'expansion':destination;if(strategyTab==='expansion')expansionTab=destination==='renewal'?'renewal':'capacity';if(destination==='decision')growthTab='copilot';page='growth';area='admin';root.classList.remove('r-menu-open');render();persist();main.scrollIntoView({block:'start'});}
 function decisionBody(){const d=T.decision(params,simulation),m=d.month,f=simulation.final,checks=T.policyChecks(params,simulation,strategy.policies),nonNull=checks.filter(c=>c.limit!==null);return `<div class="r-equal">${panel('Seu dinheiro e o retorno',row('Frota inicial viável',simulation.initial.cars.length+' de '+params.initialFleet+' solicitados','Após abertura, entrada, preparação, estoque e reserva.')+row('Capital próprio aportado',money(f.capital),'Inclui capital inicial e aportes explícitos.')+row('Lucro acumulado projetado',money(f.profitTotal),'Após depreciação, juros e tributos parametrizados.')+row('ROI sobre capital próprio',pct(d.roi),'Lucro acumulado ÷ capital aportado no horizonte.')+row('Devolvido ao proprietário',money(f.distributed),'Somente retiradas; lucro retido não é dinheiro devolvido.')+row('Capital ainda não devolvido',money(d.tied))+row('Payback por retiradas',d.distributionPayback===null?'Não alcançado':'Mês '+d.distributionPayback)+row('Lucro acumulado igual ao aporte',d.resultPayback===null?'Não alcançado':'Mês '+d.resultPayback,'Indicador contábil; não representa resgate do investimento.'))}${panel('Margem de segurança · primeiro mês',row('Ocupação de equilíbrio',pct(d.occupancyMin),'Busca no motor completo, incluindo parcela, loja e tributos; caixa após dívida = zero.')+row('Dias adicionais de parada até equilíbrio',d.daysMargin===null?'Sem folga':number(d.daysMargin)+' dias','Equivalência no primeiro mês; mantém demais premissas.')+row('Aluguel semanal de equilíbrio',money(d.weeklyMin),'Mantidas ocupação e demais premissas.')+row('Folga da ocupação',d.occupancyMin===null?'Não cobre a operação':number(params.occupancy-d.occupancyMin)+' p.p.')+row('Primeiro mês abaixo da reserva',d.reserveBreach===null?'Nenhum no horizonte':'Mês '+d.reserveBreach)+row('Primeiro caixa negativo',d.negative===null?'Nenhum no horizonte':'Mês '+d.negative)+row('Caixa livre no primeiro mês',money(m.available),'Saldo menos reserva fixa e por carro.'))}</div><div class="r-section-gap">${panel('Amortizar ou comprar?',table(['Estratégia','Frota final','Juros acumulados','Caixa final','Dívida','Patrimônio'],d.alternatives.map(a=>`<tr><td>${a.name}</td><td>${a.result.final.fleet}</td><td>${money(a.interest)}</td><td>${money(a.result.final.cash)}</td><td>${money(a.result.final.debt)}</td><td>${money(a.result.final.equity)}</td></tr>`).join(''))+`<p class="r-caption">Mesmo capital e horizonte. Amortizar usa ${money(params.extraAmort)}/mês e prioridade à dívida; comprar reinveste sem amortização extra. Todas as compras e extras preservam a reserva.</p>`)}</div><div class="r-section-gap">${panel('Comprar agora ou esperar?',table(['Próximo veículo','Viabilidade','Falta para entrada + reserva','Caixa no horizonte','Patrimônio no horizonte'],T.purchaseTiming(params).map(o=>`<tr><td>${o.wait===0?'Agora':'Esperar '+o.wait+' meses'}</td><td>${o.viable?'Cabe no caixa':'Sem caixa suficiente'}</td><td>${money(o.gap)}</td><td>${money(o.cash)}</td><td>${money(o.equity)}</td></tr>`).join(''))+'<p class="r-caption">Uma única compra adicional após a frota inicial. Horizonte comum de 24 meses; operação mantida durante a espera, sem outras compras. Inclui preparação, estoque e reserva por carro.</p>')}</div><div class="r-section-gap">${panel('Políticas aplicadas ao rascunho',nonNull.length?nonNull.map(c=>row(esc(c.label),esc(c.status),`Limite ${number(c.limit)} · calculado ${c.value===null?'sem base':number(c.value)}`)).join(''):'<p class="r-caption">Nenhum limite definido. Configure as políticas da empresa para comparar as decisões com suas próprias regras.</p>',btn('Definir políticas','strategy-policies'))}</div>`;}
 function masterView(){const a=T.allocation(book,month),timeline=T.timeline(a,strategy.policies),next=timeline.rows.find(r=>!r.achieved),milestones=T.milestones(strategy.milestones,simulation);return `<div class="r-equal">${panel('Direção da empresa',`<form id="r-master"><label class="r-field">Missão<textarea name="mission" maxlength="1500" rows="3" placeholder="Por que a RODAVOLT existe?">${esc(strategy.mission)}</textarea></label><label class="r-field r-section-gap">Visão<textarea name="vision" maxlength="1500" rows="3" placeholder="O que queremos construir?">${esc(strategy.vision)}</textarea></label><h3>Frentes futuras em estudo</h3><div class="r-quick-grid">${T.fronts.map(t=>`<label class="r-check"><input type="checkbox" name="front" value="${esc(t)}" ${strategy.fronts.includes(t)?'checked':''}>${t}</label>`).join('')}</div><div class="r-form-footer"><button class="r-button r-primary" type="submit">Salvar planejamento mestre</button></div><p class="r-caption">Frentes em estudo não criam despesas nem alteram a projeção. Não é necessário comprometer a missão com uma meta fixa de frota.</p></form>`)}${panel('Roadmap automático',next?row('Frota registrada',a.rows.length+' carros','Fechamento demonstrativo '+actual().label)+row('Próximo marco estrutural',next.fleet+' carros')+row('Veículos adicionais',next.additionalCars)+row('Capital adicional proporcional',money(next.additionalCapital),'Custo médio registrado × carros faltantes; não é caixa disponível.')+row('Resultado mensal adicional',money(next.additionalNet),'Extrapolação linear da amostra, sem ganho de escala.')+row('Amostra com histórico',timeline.sample+' veículo(s)'):'<p>Todos os marcos estruturais foram alcançados.</p>',monthPicker())}</div><div class="r-section-gap">${panel('Linha do tempo · economia observada da frota',table(['Marco','Situação','Capital','Receita/mês','Despesa/mês','Resultado/mês','Teto financiável'],timeline.rows.map(r=>`<tr><td>${r.fleet} carros</td><td>${r.achieved?'Alcançado':'Próxima etapa'}</td><td>${money(r.capital)}</td><td>${money(r.revenue)}</td><td>${money(r.expense)}</td><td>${money(r.net)}</td><td>${money(r.finance)}</td></tr>`).join(''))+'<p class="r-caption">Média dos registros demonstrativos com ao menos um mês de histórico × tamanho da frota. Sem escala, pessoal adicional ou previsão de data. O simulador empresarial calcula o crescimento completo; esta tabela explica a unidade econômica observada. Teto financiável depende da política definida.</p>')}</div><div class="r-section-gap">${panel('Meus marcos de crescimento',btn('Adicionar marco','milestone-new',true)+(milestones.length?table(['Marco','Gatilho','Projeção','Ações'],milestones.map(i=>`<tr><td>${esc(i.name)}</td><td>${T.triggers[i.trigger]} ${i.trigger==='manual'?'':number(i.value)}</td><td>${i.hit===null?'Não alcançado':i.hit==='Manual'?'Concluído manualmente':'Mês '+i.hit}</td><td>${btn('Editar','milestone-edit',false,`data-id="${i.id}"`)} ${i.trigger==='manual'?btn(i.done?'Reabrir':'Concluir','milestone-done',false,`data-id="${i.id}"`):''} ${btn('Excluir','milestone-delete',false,`data-id="${i.id}"`)}</td></tr>`).join('')):'<p class="r-caption">Crie marcos por frota, caixa, caixa livre, lucro, receita, ROI, tempo ou conclusão manual. A data projetada muda com o rascunho e não significa realização.</p>'))}</div>`;}
 function allocationView(){const a=T.allocation(book,month);return heading('CAPITAL ALLOCATION CENTER','O retorno precisa ter uma origem.','Registros confirmados da demonstração por veículo; sem valor de compra, o ROI permanece sem base.',monthPicker())+`<div class="r-kpis">${kpi('Valor de compra contabilizado',money(a.cost),a.missing+' carros sem valor informado')}${kpi('Resultado dos registros',money(a.net),'Recebimentos − despesas, antes da depreciação')}${kpi('ROI acumulado sobre compra',pct(a.roi),'Não é ROI sobre entrada financiada')}${kpi('Veículos na amostra',String(a.rows.length),'Despesas seguem o centro informado no lançamento')}</div>${panel('Ranking por ROI',table(['Veículo','Compra','Receita','Despesa','Resultado','ROI','Payback estimado','Origem'],a.rows.map(r=>`<tr><td>${r.id}</td><td>${money(r.cost)}</td><td>${money(r.revenue)}</td><td>${money(r.expense)}</td><td>${money(r.net)}</td><td>${pct(r.roi)}</td><td>${r.payback===null?'Sem base':number(r.payback)+' meses'}</td><td>${btn('Ver registros','allocation-source',false,`data-id="${r.id}"`)}</td></tr>`).join(''))+'<p class="r-caption">Payback = valor de compra ÷ média mensal do resultado registrado; não é promessa de recuperação. Receita inclui aluguel e loja; despesas incluem mercadoria, comissão, operação, tributo e juros. Principal e aquisição ficam fora do resultado. Custos corporativos aqui seguem o vínculo registrado, sem rateio automático.</p>')}<div class="r-equal r-section-gap">${panel('Maior retorno na amostra',a.rows[0]?row(a.rows[0].id,pct(a.rows[0].roi),money(a.rows[0].net)+' de resultado registrado'):'Sem histórico')}${panel('Menor retorno na amostra',a.rows.at(-1)?row(a.rows.at(-1).id,pct(a.rows.at(-1).roi),'Compare custos e tempo de operação antes de decidir vender.'):'Sem histórico')}</div>`;}
 function policiesView(){const checks=T.policyChecks(params,simulation,strategy.policies);return `${panel('Regras definidas pelo proprietário',`<form id="r-policies"><div class="r-fields">${Object.entries(T.policyLabels).map(([k,label])=>input(k,label,strategy.policies[k]??'','type="number" min="0" step="any" placeholder="Não definida"')).join('')}</div><label class="r-field r-section-gap">Outras políticas · uma por linha (nome = valor)<textarea name="custom" rows="3" maxlength="2000" placeholder="Limite de custo por km = 0.25">${esc(Object.entries(strategy.custom).map(([k,v])=>k+' = '+v).join('\n'))}</textarea></label><div class="r-form-footer"><button type="submit" class="r-button r-primary">Salvar políticas</button>${btn('Aplicar reserva e teto de financiamento ao rascunho','apply-policies')}</div><p class="r-caption">Campo vazio significa não definido. Os limites são comparados com o rascunho, sem executar ações. O botão de aplicação altera apenas reserva mínima e percentual financiado; as demais regras geram comparações. Marketing, tecnologia e políticas livres ficam sem avaliação automática até existir uma base correspondente.</p></form>`)}<div class="r-section-gap">${panel('Conferência do cenário atual',table(['Política','Limite','Calculado','Conferência'],checks.map(c=>`<tr><td>${esc(c.label)}</td><td>${c.limit===null?'Não definido':number(c.limit)}</td><td>${c.value===null?'Sem base':number(c.value)}</td><td>${c.status}</td></tr>`).join(''))+'<p class="r-caption">ROI é acumulado no horizonte; payback usa retiradas ao proprietário. Alavancagem usa dívida / valor dos carros ao final. Crescimento compara o mês 12 com a frota inicial. Reserva considera o menor caixa desde a aquisição; caixa em meses considera despesas + parcelas no primeiro mês.</p>')}</div>`;}
 const expansionFields=[['capital','Capital disponível · R$',0],['reserve','Reserva mínima · R$',0],['price','Preço do veículo · R$',1],['entry','Entrada por veículo · R$',1],['rate','Juros mensais · %',0],['term','Prazo · meses',1],['weekly','Aluguel semanal · R$',0],['occupancy','Ocupação · %',0],['km','Km por mês',0],['insurance','Seguro mensal · R$',0],['annualTax','IPVA anual · R$',0],['tracker','Rastreador mensal · R$',0],['maintenance','Manutenção + pneus por km · R$',0],['admin','Administração mensal · R$',0],['horizon','Horizonte · meses',1],['saleAge','Vender projetados após · meses',1],['saleValue','Venda estimada por veículo · R$',0],['saleFee','Custo de venda · %',0],['dscrHealthy','DSCR saudável · vezes',0],['dscrMin','DSCR de atenção · vezes',0]];
 function expansionView(){const x=T.expansion(strategy.expansion,actual(),book),e=x.e,r=x.selected.growth,f=r.meses.at(-1);return `<div class="r-note"><strong>Planejamento de expansão e renovação.</strong> ${expansionTab==='renewal'?'Estudo independente de um veículo hipotético, com a entrada e o preço informados; não utiliza o caixa nem a frota do fechamento.':e.source==='observed'?'Partida no fechamento demonstrativo '+actual().label+'; receitas futuras usam o contrato ativo do RV-001, custos são premissas.':'Cenário independente: usa apenas o capital informado, sem incluir a frota cadastrada.'} Os cenários desta área usam valor dos carros constante e excluem loja, depreciação e tributos. A central de decisão mantém o modelo empresarial completo.</div><details class="r-section-gap" ${expansionTab==='assumptions'?'open':''}><summary>Premissas da expansão · ${esc(e.name)}</summary><form id="r-expansion"><div class="r-fields">${input('name','Nome do cenário',e.name,'maxlength="100" required')}${choice('source','Ponto de partida',e.source,[['scenario','Capital hipotético · frota nova'],['observed','Fechamento demonstrativo · frota existente']])}${choice('system','Sistema de amortização',e.system,[['price','Price'],['sac','SAC']])}${choice('strategy','Estratégia selecionada',e.strategy,[['conservadora','Conservadora'],['balanceada','Balanceada'],['agressiva','Agressiva']])}${choice('method','Método de crescimento',e.method,[['caixa_operacional','Caixa operacional'],['caixa_e_venda','Caixa + venda recorrente dos projetados']])}${expansionFields.map(([k,label,min])=>input(k,label,e[k],`type="number" min="${min}" step="${['term','horizon','saleAge'].includes(k)?1:'any'}" required`)).join('')}</div><div class="r-form-footer"><button type="submit" class="r-button r-primary">Recalcular expansão</button>${btn('Usar premissas do simulador empresarial','expansion-import')}${btn('Preservar este cenário','expansion-save')}</div><p class="r-caption">Ao partir do fechamento, capital informado é substituído pelo caixa registrado, sem aporte adicional. Dívidas existentes preservam taxa e prestação contratadas. O cronograma remanescente preserva a prestação contratada; novas compras podem usar SAC. Valor de venda é premissa fixa, sem FIPE automática.</p></form></details>${tabs([['capacity','Capacidade hoje'],['compound','Crescimento composto'],['renewal','Inteligência de renovação'],['saved','Cenários preservados']],expansionTab,'expansion-tab')}${expansionKpis(x)}${expansionTab==='renewal'?renewalView(e):expansionTab==='saved'?savedExpansionView():expansionTab==='compound'?compoundView(x):capacityView(x)+recyclableView()} `;}
 function expansionKpis(x){if(expansionTab==='renewal'){const r=T.renewal(x.e).best;return `<div class="r-kpis">${kpi('Frota na melhor alternativa',String(r.frotaFinalUnidades),'Estudo de renovação · '+x.e.horizon+' meses')}${kpi('Caixa na melhor alternativa',money(r.caixaFinal),'Após venda e reinvestimento simulados')}${kpi('Capital reciclado',money(r.capitalReciclado),'Venda menos dívida e custos de venda')}${kpi('Patrimônio na melhor alternativa',money(r.patrimonioFinalNoHorizonte),'Mesmo horizonte para manter e vender')}</div>`;}const r=x.selected.growth,e=x.e;return `<div class="r-kpis">${kpi('Frota final',String(r.frotaFinal),e.strategy+' · '+e.horizon+' meses')}${kpi('Caixa da expansão',money(r.caixaFinal),'Somente a fração de capital aplicada à estratégia')}${kpi('Dívida final',money(r.dividaFinal),'Dívidas existentes + novas aquisições')}${kpi('Patrimônio do cenário',money(r.patrimonioFinal),'Caixa + ativos − dívida; valor dos carros constante')}</div>`;}
 function capacityView(x){return panel('Quantos novos carros cabem agora?',table(['Estratégia','Capital utilizável','Reserva aplicada','Novos carros','Capital nas entradas','Parcela/carro','Próxima entrada'],x.all.map(a=>`<tr><td>${a.key}</td><td>${money(a.capacity.capitalDisponivelParaAquisicao)}<small>${number(a.parameters.fracaoCapitalUsavel*100)}% do capital</small></td><td>${money(a.capacity.reservaMinimaAplicada)}<small>${number(a.parameters.multiplicadorReserva)}× a reserva</small></td><td>${a.capacity.veiculosAdicionadosTotal}</td><td>${money(a.capacity.capitalUsadoTotal)}</td><td>${money(a.capacity.parcelaMensalPorVeiculo)}</td><td>${a.capacity.proximoMarco.possivel?'Mês '+a.capacity.proximoMarco.mesesAteProximoVeiculo:a.capacity.proximoMarco.motivo}</td></tr>`).join(''))+'<p class="r-caption">Capacidade estática de um lote novo. Conservadora usa 50% do capital e reserva 1,5×; balanceada 75% e 1×; agressiva 100% e 0,5×. São parâmetros herdados do cenário, não normas de mercado. Patrimônio de carros e venda futura não são caixa disponível. A tabela composta aplica também a trava de cobertura das parcelas (DSCR).</p>')+`<div class="r-section-gap">${panel('Frota existente no ponto de partida',x.seed.length?table(['Veículo','Valor estimado','Dívida','Receita mensal do contrato'],x.seed.map(c=>`<tr><td>${esc(c.identificador)}</td><td>${money(c.valorAtual)}</td><td>${money(c.saldoDevedorAtual)}</td><td>${money(c.receitaMensalReal)}</td></tr>`).join('')):'<p class="r-caption">Cenário independente: nenhum carro cadastrado está sendo incluído. Edite o ponto de partida nas premissas para usar um fechamento.</p>')}</div>`;}
 function recyclableView(){const r=T.recyclable(actual(),strategy.saleCandidates||[],strategy.expansion.saleFee);return `<div class="r-section-gap">${panel('Capital reciclável potencial · frota registrada',row('Venda líquida estimada',money(r.total),'Informativo: não soma ao caixa da expansão; valor negativo exige dinheiro para quitar a dívida.')+`<form id="r-recyclable"><div class="r-fields">${choice('vehicle','Veículo candidato à venda',actual().snapshot.cars[0]?.id||'',actual().snapshot.cars.map(c=>[c.id,c.id]))}${input('value','Valor de venda estimado · R$',strategy.expansion.saleValue,'type="number" min="0" step=".01" required')}</div><div class="r-form-footer"><button type="submit" class="r-button">Incluir ou atualizar candidato</button></div></form>`+(r.rows.length?table(['Veículo','Venda estimada','Dívida a quitar','Custo de venda','Líquido','Ação'],r.rows.map(v=>`<tr><td>${v.id}</td><td>${money(v.value)}</td><td>${money(v.debt)}</td><td>${money(v.cost)}</td><td>${money(v.net)}</td><td>${btn('Retirar candidato','recycle-remove',false,`data-id="${v.id}"`)}</td></tr>`).join('')):'<p class="r-caption">Selecione apenas os carros que deseja estudar vender. Nenhuma venda é presumida pela existência de patrimônio.</p>'))}</div>`;}
 function compoundView(x){const r=x.selected.growth;return panel('Próxima aquisição além do horizonte',r.proximoVeiculo.possivel?row('Veículo #'+r.proximoVeiculo.numero,'Mês '+r.proximoVeiculo.mesEstimado,'Capital necessário '+money(r.proximoVeiculo.capitalNecessario)):row('Motivo',esc(r.proximoVeiculo.motivo),'Falta '+money(r.proximoVeiculo.gap)+' · capital mínimo '+money(r.proximoVeiculo.capitalNecessario)))+'<div class="r-section-gap"></div>'+panel('Comparação das três estratégias',table(['Estratégia','Frota final','Comprados / vendidos','Caixa','Dívida','Patrimônio','Déficit de caixa a financiar'],x.all.map(a=>`<tr><td>${a.key}</td><td>${a.growth.frotaFinal}</td><td>${a.growth.veiculosCompradosTotal} / ${a.growth.veiculosVendidosTotal}</td><td>${money(a.growth.caixaFinal)}</td><td>${money(a.growth.dividaFinal)}</td><td>${money(a.growth.patrimonioFinal)}</td><td>${money(a.growth.capitalExternoNecessario)}</td></tr>`).join('')))+`<div class="r-section-gap">${panel('Fluxo composto · '+x.e.strategy,table(['Mês','Frota','Compra / venda','Caixa inicial','Receita','Custos','Juros / principal','Venda líquida','Caixa final','Dívida','Patrimônio','DSCR'],r.meses.map(m=>`<tr><td>${m.mes}</td><td>${m.frotaTotal}</td><td>${m.veiculosComprados} / ${m.veiculosVendidos}</td><td>${money(m.caixaInicial)}</td><td>${money(m.receita)}</td><td>${money(m.custosOperacionais)}</td><td>${money(m.jurosDoMes)}<small>${money(m.amortizacaoDoMes)}</small></td><td>${money(m.produtoLiquidoVendas)}</td><td>${money(m.caixaFinal)}</td><td>${money(m.dividaTotal)}</td><td>${money(m.patrimonioLiquido)}</td><td>${m.dscr===null?'Sem parcela':number(m.dscr)+'×'}</td></tr>`).join(''))+`<p class="r-caption">Mês 0 é posição inicial; novas compras operam no mês seguinte. Venda recorrente só alcança carros projetados; os existentes permanecem. Resultado não inclui tributos, loja ou depreciação. DSCR = receita − custos operacionais, dividido pelas parcelas.</p>`)}</div><div class="r-section-gap">${panel('Por que comprou, vendeu ou bloqueou?',table(['Mês','Evento','Explicação','Valores da decisão'],r.eventos.map(ev=>`<tr><td>${ev.mes}</td><td>${ev.tipo}</td><td>${esc(ev.descricao)}</td><td>${Object.entries(ev.numeros).map(([k,v])=>esc(k)+': '+number(v)).join('<br>')}</td></tr>`).join('')))}</div>`;}
 function renewalView(e){const r=T.renewal(e),best=r.best;return `${panel('Quando vender este veículo hipotético?',`<h3>${best.mesVenda===null?'Manter até o final':'Vender no mês '+best.mesVenda}</h3>${r.explicacao.map(t=>`<p class="r-caption">${esc(t)}</p>`).join('')}`)}<div class="r-section-gap">${renewalBars('Patrimônio final por momento de venda',r.porMomento,'patrimonioFinalNoHorizonte')}</div><div class="r-equal r-section-gap">${renewalBars('Capital reciclado por momento',r.porMomento,'capitalReciclado')}${renewalBars('Frota final por alternativa',r.porMomento,'frotaFinalUnidades','carros')}</div><div class="r-section-gap">${panel('Alternativas no mesmo horizonte',table(['Venda','Patrimônio final','Caixa','Equity nos carros','Capital reciclado','Frota final','Retorno operacional','Detalhe'],r.porMomento.map(o=>`<tr><td>${o.mesVenda===null?'Manter':'Mês '+o.mesVenda}${o===best?' · melhor nas premissas':''}</td><td>${money(o.patrimonioFinalNoHorizonte)}</td><td>${money(o.caixaFinal)}</td><td>${money(o.equityFinal)}</td><td>${money(o.capitalReciclado)}</td><td>${o.frotaFinalUnidades}</td><td>${money(o.retornoOperacionalAcumulado)}</td><td>${btn('Abrir memória','renewal-detail',false,`data-month="${o.mesVenda??'keep'}"`)}</td></tr>`).join(''))+`<p class="r-caption">Comparação isolada de um carro financiado pela entrada informada, venda em passos de 3 meses (até 12 alternativas) ou manutenção até o fim. Reinvestimento limitado por reserva e DSCR. Preço de venda fixo de ${money(e.saleValue)} em todas as datas: é hipótese, sem cotação. Capital reciclado não equivale ao retorno operacional.</p>`)}</div>`;}
 function businessScenarios(){strategy.businessScenarios||=[];return panel('Meus cenários empresariais',`<form id="r-business-scenario"><div class="r-fields">${input('name','Nome do cenário','','required maxlength="100" placeholder="Ex.: compra do primeiro carro"')}</div><div class="r-form-footer"><button type="submit" class="r-button r-primary">Preservar rascunho como cenário</button></div></form>`+(strategy.businessScenarios.length?table(['Cenário','Frota final','Caixa','Patrimônio','Ações'],strategy.businessScenarios.map((v,i)=>{const r=S.simulate(v.params);return `<tr><td>${esc(v.name)}</td><td>${r.final.fleet}</td><td>${money(r.final.cash)}</td><td>${money(r.final.equity)}</td><td>${btn('Carregar cópia','business-load',false,`data-index="${i}"`)} ${btn('Excluir','business-delete',false,`data-index="${i}"`)}</td></tr>`;}).join('')):'<p class="r-caption">Preserve quantos cenários precisar. Carregar uma cópia muda o rascunho, mantendo o plano original da comparação.</p>'))+'<div class="r-section-gap"></div>';}
 function renewalBars(title,options,key,unit='R$'){const vals=options.map(o=>o[key]),min=Math.min(0,...vals),max=Math.max(1,...vals),span=max-min;return panel(title,`<div class="r-strategy-bars" role="img" aria-label="${title}">${options.map(o=>{const v=o[key],zero=-min/span*100,end=(v-min)/span*100;return `<div class="r-bar-row"><span>${o.mesVenda===null?'Manter':'Mês '+o.mesVenda}</span><div class="r-bar-track"><i style="left:${Math.min(zero,end)}%;width:${Math.abs(end-zero)}%"></i></div><strong>${unit==='R$'?money(v):number(v)+' carros'}</strong></div>`;}).join('')}</div>`);}
 function savedExpansionView(){return panel('Cenários de expansão preservados',strategy.scenarios.length?strategy.scenarios.map((s,i)=>row(esc(s.name),esc(new Date(s.at).toLocaleString('pt-BR')),`${s.input.horizon} meses · ${s.input.system.toUpperCase()} · ${s.input.strategy}`)+btn('Carregar cópia','expansion-load',false,`data-index="${i}"`)+btn('Excluir cenário','expansion-delete',false,`data-index="${i}"`)).join(''):'<p class="r-caption">Abra as premissas, recalcule e use “Preservar este cenário”. As cópias não mudam quando o rascunho é editado.</p>');}
 function milestoneForm(item=null){return `<form id="r-milestone"><input type="hidden" name="milestoneId" value="${item?.id||''}">${input('name','Nome do marco',item?.name||'','required maxlength="100"')}${choice('trigger','Gatilho',item?.trigger||'veiculos',Object.entries(T.triggers))}${input('value','Valor do gatilho (ignorado no manual)',item?.value??5,'type="number" min="0" step="any"')}<div class="r-form-footer"><button type="submit" class="r-button r-primary">Salvar marco</button></div></form>`;}
 function strategyAction(action,e){
  if(action==='recycle-remove'){strategy.saleCandidates=strategy.saleCandidates.filter(c=>c.id!==e.dataset.id);render();persist();return true;}
  if(action==='business-load'){params=S.validate(structuredClone(strategy.businessScenarios[Number(e.dataset.index)].params));render();persist();toast('Cópia carregada no rascunho. O plano original foi preservado.');return true;}
  if(action==='business-delete'){strategy.businessScenarios.splice(Number(e.dataset.index),1);render();persist();return true;}
  if(action==='strategy-policies'){strategyTab='policies';render();persist();return true;}
  if(action==='milestone-new'||action==='milestone-edit'){drawer('Marco de crescimento',milestoneForm(strategy.milestones.find(m=>m.id===e.dataset.id)));return true;}
  if(action==='milestone-done'){const i=strategy.milestones.find(m=>m.id===e.dataset.id);i.done=!i.done;C.log(book,'Marco manual atualizado',i.id,i.done?'Concluído':'Reaberto');render();persist();return true;}
  if(action==='milestone-delete'){strategy.milestones=strategy.milestones.filter(m=>m.id!==e.dataset.id);C.log(book,'Marco excluído',e.dataset.id,'Exclusão no planejamento local.');render();persist();return true;}
  if(action==='allocation-source'){const r=T.allocation(book,month).rows.find(r=>r.id===e.dataset.id);drawer('Origem do retorno · '+r.id,table(['Registro','Categoria','Mês','Valor','Fonte'],book.entries.filter(v=>r.sources.includes(v.id)).map(v=>`<tr><td>${v.id}</td><td>${esc(categoryNames[v.category]||v.category)}</td><td>${v.month}</td><td>${cents(v.amount)}</td><td>${esc(v.source)}</td></tr>`).join('')));return true;}
  if(action==='apply-policies'){const p=strategy.policies;params=S.validate({...params,...(p.capital_reserva_valor===null?{}:{reserveFixed:Math.max(params.reserveFixed,p.capital_reserva_valor)}),...(p.financiamento_maximo_pct===null?{}:{downPct:Math.max(params.downPct,100-p.financiamento_maximo_pct)})});C.log(book,'Políticas aplicadas','Rascunho','Reserva e entrada ajustadas; plano original preservado.');render();persist();toast('Reserva e teto financiável aplicados apenas ao rascunho.');return true;}
  if(action==='expansion-import'){strategy.expansion={...strategy.expansion,capital:params.initialCapital,reserve:params.reserveFixed+params.reservePerCar,price:params.price,entry:params.financed?params.price*params.downPct/100:params.price,rate:params.monthlyRate,term:params.term,weekly:params.weekly,occupancy:params.occupancy,km:params.kmPerDay*28,insurance:params.insurance,annualTax:params.annualTax,tracker:params.tracker,maintenance:params.maintenanceKm+params.tiresKm,admin:params.admin,horizon:params.horizon};render();persist();toast('Premissas comuns copiadas. Custos e regras excluídos deste motor continuam indicados na tela.');return true;}
  if(action==='expansion-save'){strategy.scenarios.push({name:strategy.expansion.name,at:new Date().toISOString(),input:structuredClone(strategy.expansion)});C.log(book,'Cenário de expansão preservado',strategy.expansion.name,'Cópia das premissas recalculadas.');expansionTab='saved';render();persist();toast('Cenário recalculado preservado.');return true;}
  if(action==='expansion-load'){strategy.expansion=structuredClone(strategy.scenarios[Number(e.dataset.index)].input);expansionTab='capacity';render();persist();return true;}
  if(action==='expansion-delete'){strategy.scenarios.splice(Number(e.dataset.index),1);render();persist();return true;}
  if(action==='renewal-detail'){const c=T.renewalScenario(strategy.expansion),m=e.dataset.month==='keep'?null:Number(e.dataset.month),r=L.simularMomentoDeVenda(c,m);drawer('Memória de renovação · '+(m===null?'manter':'mês '+m),panel('Composição da decisão',row('Patrimônio final',money(r.patrimonioFinalNoHorizonte))+row('Caixa final',money(r.caixaFinal))+row('Capital reciclado',money(r.capitalReciclado))+row('Capital usado em novas entradas',money(r.capitalRecicladoUsadoEmNovaAquisicao))+row('Receita acumulada',money(r.receitaAcumulada))+row('Juros acumulados',money(r.jurosAcumulados))+row('Principal pago',money(r.amortizacaoAcumulada)))+table(['Mês','Frota','Receita','Custos','Juros / principal','Caixa','Dívida','Equity','Patrimônio'],r.meses.map(o=>`<tr><td>${o.mes}</td><td>${o.frotaAtiva}</td><td>${money(o.receita)}</td><td>${money(o.custosOperacionais)}</td><td>${money(o.jurosDoMes)} / ${money(o.amortizacaoDoMes)}</td><td>${money(o.caixa)}</td><td>${money(o.saldoDevedor)}</td><td>${money(o.equity)}</td><td>${money(o.patrimonio)}</td></tr>`).join(''))+panel('Eventos e bloqueios',r.eventos.map(ev=>`<p class="r-caption">${esc(JSON.stringify(ev))}</p>`).join('')));return true;}
  return false;
 }
 function strategySubmit(form,f){let handled=true;
  if(form.id==='r-recyclable'){const id=String(f.get('vehicle')),value=Number(f.get('value'));T.recyclable(actual(),[{id,value}],strategy.expansion.saleFee);strategy.saleCandidates=[...(strategy.saleCandidates||[]).filter(c=>c.id!==id),{id,value}];C.log(book,'Candidato à reciclagem atualizado',id,'Premissa de venda; sem alteração no caixa.');}
  else if(form.id==='r-business-scenario'){const name=String(f.get('name')).trim();if(!name)throw new RangeError('Informe o nome.');(strategy.businessScenarios||=[]).push({name,params:structuredClone(params),at:new Date().toISOString()});C.log(book,'Cenário empresarial preservado',name,'Cópia do rascunho.');}
  else if(form.id==='r-master'){strategy.mission=String(f.get('mission')).trim();strategy.vision=String(f.get('vision')).trim();strategy.fronts=f.getAll('front').filter(v=>T.fronts.includes(v));C.log(book,'Planejamento mestre salvo','Estratégia','Missão, visão e frentes futuras.');}
  else if(form.id==='r-policies'){const p=T.validatePolicies(Object.fromEntries(f)),custom={};for(const line of String(f.get('custom')).split('\n').filter(l=>l.trim())){const match=line.match(/^(.+?)\s*=\s*([\d.,]+)$/);if(!match||!Number.isFinite(Number(match[2].replace(',','.'))))throw new RangeError('Use nome = valor nas políticas livres.');custom[match[1].trim()]=Number(match[2].replace(',','.'));}strategy.policies=p;strategy.custom=custom;C.log(book,'Políticas atualizadas','Estratégia','Limites definidos pelo proprietário.');}
  else if(form.id==='r-milestone'){const trigger=f.get('trigger'),value=trigger==='manual'?null:Number(f.get('value')),name=String(f.get('name')).trim();if(!name||!T.triggers[trigger]||value!==null&&(!Number.isFinite(value)||value<0))throw new RangeError('Revise nome, gatilho e valor.');const existing=strategy.milestones.find(m=>m.id===f.get('milestoneId')),item={id:existing?.id||'MAR-'+Date.now(),name,trigger,value,done:existing?.done||false,active:true};if(existing)Object.assign(existing,item);else strategy.milestones.push(item);C.log(book,'Marco salvo',item.id,name);root.querySelector('#r-drawer').hidden=true;}
  else if(form.id==='r-expansion'){const values={...strategy.expansion};for(const [k]of expansionFields)values[k]=Number(f.get(k));for(const k of ['name','source','system','strategy','method'])values[k]=String(f.get(k));const checked=T.validateExpansion(values);T.expansion(checked,actual(),book);T.renewal(checked);strategy.expansion=checked;C.log(book,'Expansão recalculada',strategy.expansion.name,'Premissas locais atualizadas.');}
  else handled=false;
  if(handled){render();persist();toast('Planejamento salvo nesta demonstração local.');}return handled;
 }
